const address="Umm Hurair 2";let map=L.map("map").setView([0,0],2);async function initMap(){try{const url=`${base_url}assets/frontend/ultimate/js/proxy.php?address=${encodeURIComponent(address)}`,response=await fetch(url),data=await response.json();if(data.length>0){const latitude=data[0].lat,longitude=data[0].lon;map.setView([latitude,longitude],15),L.marker([latitude,longitude]).addTo(map).bindPopup(address).openPopup()}else console.error("Adresse introuvable."),document.getElementById("map").innerHTML="<p>Adresse introuvable. Veuillez vérifier l'adresse.</p>"}catch(error){console.error("Erreur de géocodage :",error)}}L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map),document.addEventListener("DOMContentLoaded",initMap);